'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var hasProp = require( '@stdlib/assert/has-property' );
var isUndefined = require( '@stdlib/assert/is-undefined' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var Legend = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Legend, 'function', 'main export is a function' );
	t.end();
});

tape( 'the constructor returns an instance which has a `labelFontWeight` property', function test( t ) {
	var v;

	v = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( hasOwnProp( v, 'labelFontWeight' ), false, 'returns expected value' );
	t.strictEqual( hasProp( v, 'labelFontWeight' ), true, 'returns expected value' );
	t.strictEqual( isUndefined( v.labelFontWeight ), true, 'returns expected value' );

	v = new Legend({
		'fill': 'colorScale',
		'labelFontWeight': 'bold'
	});
	t.strictEqual( isString( v.labelFontWeight ), true, 'returns expected value' );

	v = new Legend({
		'fill': 'colorScale',
		'labelFontWeight': 200
	});
	t.strictEqual( isString( v.labelFontWeight ), true, 'returns expected value' );
	t.end();
});

tape( 'the constructor returns an instance having a `labelFontWeight` property which throws an error if set to an invalid value', function test( t ) {
	var values;
	var i;

	values = [
		null,
		true,
		false,
		[],
		{},
		function noop() {}
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[ i ] ), TypeError, 'throws an error when provided ' + values[ i ] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var legend = new Legend({
				'fill': 'colorScale'
			});
			legend.labelFontWeight = value;
		};
	}
});

tape( 'the constructor returns an instance having a `labelFontWeight` property', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	t.strictEqual( isUndefined( legend.labelFontWeight ), true, 'returns expected value' );

	legend = new Legend({
		'fill': 'colorScale',
		'labelFontWeight': 'bold'
	});
	t.strictEqual( legend.labelFontWeight, 'bold', 'returns expected value' );

	legend = new Legend({
		'fill': 'colorScale',
		'labelFontWeight': 200
	});
	t.strictEqual( legend.labelFontWeight, '200', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `labelFontWeight` property which can be set to a valid string value', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});

	legend.labelFontWeight = 'bold';
	t.strictEqual( legend.labelFontWeight, 'bold', 'returns expected value' );

	legend.labelFontWeight = 'normal';
	t.strictEqual( legend.labelFontWeight, 'normal', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance having a `labelFontWeight` property which can be set to a valid numeric value', function test( t ) {
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});

	legend.labelFontWeight = 100;
	t.strictEqual( legend.labelFontWeight, '100', 'returns expected value' );

	legend.labelFontWeight = 900;
	t.strictEqual( legend.labelFontWeight, '900', 'returns expected value' );

	t.end();
});

tape( 'the constructor returns an instance which emits an event when the `labelFontWeight` property is set to a new value (string)', function test( t ) {
	var count;
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	count = 0;

	legend.on( 'change', onChange );

	legend.labelFontWeight = 'bold';
	t.strictEqual( count, 1, 'returns expected value' );

	legend.labelFontWeight = 'normal';
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	legend.labelFontWeight = 'normal';
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});

tape( 'the constructor returns an instance which emits an event when the `labelFontWeight` property is set to a new value (number)', function test( t ) {
	var count;
	var legend;

	legend = new Legend({
		'fill': 'colorScale'
	});
	count = 0;

	legend.on( 'change', onChange );

	legend.labelFontWeight = 100;
	t.strictEqual( count, 1, 'returns expected value' );

	legend.labelFontWeight = 900;
	t.strictEqual( count, 2, 'returns expected value' );

	// Setting to the same value should not emit an event:
	legend.labelFontWeight = 900;
	t.strictEqual( count, 2, 'returns expected value' );

	t.end();

	function onChange() {
		count += 1;
	}
});
